	permIdx := make([]int, m)
	remaining := make([]int, m)
	for i := 0; i < m; i++ {
		remaining[i] = i
	}
	rem := k - 1 // 0-indexed
	for i := 0; i < m; i++ {
		f := fact[m-1-i]
		idx := int(rem / f)
		rem %= f
		permIdx[i] = remaining[idx]
		// Remove remaining[idx]
