	// Position: n-m+1 + i (for i in 0..m-1)
	// Value: (n-m+1) + permIdx[i]
	for i := 0; i < m; i++ {
		pos := n - m + 1 + int64(i)
		val := n - m + 1 + int64(permIdx[i])
