// factorial with cap to avoid overflow; returns math.MaxInt64 if exceeds
func factorial(n int) int64 {
	if n <= 0 {
		return 1
	}
	result := int64(1)
	for i := 2; i <= n; i++ {
		result *= int64(i)
		if result > math.MaxInt64/int64(i) {
			return math.MaxInt64
		}
	}
	return result
