func splitLine(line []byte) []string {
	var fields []string
	var current []byte
	for _, b := range line {
		if b == ' ' || b == '\t' || b == '\n' || b == '\r' {
			if len(current) > 0 {
				fields = append(fields, string(current))
				current = nil
			}
		} else {
			current = append(current, b)
		}
	}
	if len(current) > 0 {
		fields = append(fields, string(current))
	}
	return fields
}
