func split(s string) []string {
	var result []string
	var current string
	for _, c := range s {
		if c == ' ' || c == '\n' || c == '\r' || c == '\t' {
			if current != "" {
				result = append(result, current)
				current = ""
			}
		} else {
			current += string(c)
		}
	}
	if current != "" {
		result = append(result, current)
	}
	return result
}
