func isLucky(x int) bool {
	if x <= 0 {
		return false
	}
	for x > 0 {
		d := x % 10
		if d != 4 && d != 7 {
			return false
		}
		x /= 10
	}
	return true
}

func countLucky(n int) int {
	count := 0
	for i := 1; i <= n; i++ {
		if isLucky(i) {
			count++
		}
	}
	return count
}

// factorial with cap to avoid overflow; returns 0 if exceeds maxVal
func factorial(n int, maxVal int) int {
	if n <= 0 {
		return 1
	}
	result := 1
	for i := 2; i <= n; i++ {
		result *= i
		if result > maxVal {
			return maxVal + 1
		}
	}
	return result
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
