	fact := 1
	exceeds := false
	for i := 2; i <= n; i++ {
		fact *= i
		if fact >= k {
			break
		}
		if fact > 1e18 { // avoid overflow
			exceeds = true
			break
		}
	}
	if !exceeds && fact < k {
		fmt.Println("-1")
		return
	}

	// Generate the k-th permutation (1-indexed)
	// We'll use the standard algorithm
	// First, create a list of numbers 1..n
	nums := make([]int, n)
	for i := 0; i < n; i++ {
		nums[i] = i + 1
	}

	// k is 1-indexed, convert to 0-indexed
	k-- // now k is 0-indexed

